"""Recompute every number and table in the report from study data.

Steps
  1. Run the three analyses (commitment, sweep, recovery) on the raw study data.
  2. Turn their outputs into LaTeX macros (one per quoted number) and LaTeX tables.
  3. With --check, compare the result with the committed report/numbers.tex and
     report/tables/*.tex and fail on any difference.

By default the recorded data in results/data/ are used and the outputs are written
to report/ (numbers.tex, tables/) and results/data/report_numbers.json. With
--data results/rerun (regenerated by run_experiments.py --mode full) everything is
written under results/rerun/ instead, and --check compares it with the committed report.

Usage:
    python experiments/reproduce_report.py --check
    python experiments/reproduce_report.py --data results/rerun --check
"""
from __future__ import annotations

import argparse
import importlib
import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from common import DATA, REPORT, ROOT, config, read_csv, write_json  # noqa: E402

import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402

N: dict[str, str] = {}


# ----------------------------------------------------------------------------- formatting
def put(name: str, value, fmt: str = "{:.2f}") -> None:
    assert name.isalpha() and name not in N, name
    v = value if isinstance(value, str) else fmt.format(value)
    if v[:1] in "+-" and v.lstrip("+-").replace(".", "").strip("0") == "":
        v = v[1:]                       # no sign on a zero
    if v.startswith("-"):
        v = r"\ensuremath{-}" + v[1:]   # a true minus sign in text and in math mode
    N[name] = v


def ci(name, est, lo, hi, scale=1., fmt="{:.2f}", sign=False) -> None:
    f = ("{:+" + fmt[2:]) if sign else fmt
    put(name, f.format(scale * est))
    put(name + "Lo", f.format(scale * lo))
    put(name + "Hi", f.format(scale * hi))
    put(name + "Abs", fmt.format(abs(scale * est)))


def comma(n) -> str:
    return f"{int(n):,}".replace(",", "{,}")


# ----------------------------------------------------------------------------- Experiment A
def commitment(root: Path) -> None:
    d = root / "commitment"
    prim = json.loads((d / "primary.json").read_text())
    con = pd.read_csv(d / "contrasts.csv")
    tune, test = read_csv(d / "tune.csv.gz"), read_csv(d / "test.csv.gz")
    put("CommitTuneRuns", comma(len(tune)))
    put("CommitTestRuns", comma(len(test)))
    put("CommitCells", str(prim["cells_tuned"]))
    put("CommitNeverFreeze", str(prim["cells_choosing_rolling"]))
    p = prim["primary"]
    ci("FcfsMinusRolling", *(p["fcfs-rolling"][k] for k in ("est", "lo", "hi")))
    ci("FreezeInfMinusRolling", *(p["freeze_inf-rolling"][k] for k in ("est", "lo", "hi")))
    ci("FreezeFourMinusRolling", *(p["freeze_4-rolling"][k] for k in ("est", "lo", "hi")), fmt="{:.3f}")
    ci("StopMinusTuned", *(p["adaptive-tuned_freeze"][k] for k in ("est", "lo", "hi")), scale=1e5, fmt="{:.1f}")
    for a, tag in (("freeze_4", "FreezeFour"), ("freeze_inf", "FreezeInf"), ("fcfs", "Fcfs"), ("adaptive", "Stop")):
        g = con[con.a == a]
        put(f"{tag}Min", g.est.min(), "{:.2f}" if a != "adaptive" else "{:.4f}")
        put(f"{tag}Max", g.est.max(), "{:.2f}" if a != "adaptive" else "{:.4f}")
    put("FreezeFourMinThree", con[con.a == "freeze_4"].est.min(), "{:.3f}")
    put("FreezeFourMaxThree", con[con.a == "freeze_4"].est.max(), "{:.3f}")
    put("StopSignificant", str(int((con[con.a == "adaptive"].p_holm < 0.05).sum())))
    curve = pd.read_csv(d / "tuning_curve.csv")
    put("TuneCurveMin", curve.est.min(), "{:.3f}")      # smallest freeze cost in any cell
    put("TuneCurveNeg", str(int((curve.hi < 0).sum())))  # cells/horizons where freezing was significantly better


# ----------------------------------------------------------------------------- Experiments B, C
def sweep(root: Path) -> None:
    d = root / "sweep"
    C = config("sweep")
    st = pd.read_csv(d / "structure.csv")
    cells = pd.read_csv(d / "cells.csv")
    pb = json.loads((d / "primary.json").read_text())
    put("SweepStreams", str(len(C["rho"]) * len(C["sigma"]) * len(C["hf"]) * C["test"]))
    put("SweepForks", comma(st.forks.sum()))
    put("SweepImproving", comma(st.improving.sum()))
    put("SweepReorders", comma(st.reorders.sum()))
    put("SweepShortDirect", comma(st.short_direct.sum()))
    put("SweepRescued", comma(st.rescuable.sum()))
    put("SweepRescuedShare", 100 * st.rescuable.sum() / st.reorders.sum(), "{:.0f}")
    put("SweepStillShort", comma(st.short_after_detour.sum()))
    put("SweepReorderShare", 100 * st.reorders.sum() / st.improving.sum(), "{:.0f}")
    r = pb["H3_primary"]["realized"]
    ci("SweepPrimary", r["est"], r["lo"], r["hi"], fmt="{:.1f}", sign=True)
    put("SweepPrimaryForks", comma(pb["H3_primary"]["forks"]))
    put("SweepMinHolm", pd.DataFrame(pb["H3_family"]).p_holm.min())
    put("SweepMenuMax", cells["menu-nominal@0.1/0.9"].max())
    ob = cells["oblivious-nominal@0.1/0.9"]
    put("SweepObliviousNegEst", str(int((ob < 0).sum())))
    put("SweepObliviousNeg", str(int((cells["oblivious-nominal@0.1/0.9:hi"] < 0).sum())))
    put("SweepAwareNonNeg", str(int((cells["aware-nominal@0.1/0.9"] >= 0).sum())))
    put("SweepObliviousMin", ob.min(), "{:+.1f}")
    put("SweepObliviousMax", ob.max(), "{:+.1f}")
    rec = cells["oblivious-nominal@0/1"]
    put("SweepRecMin", rec.min(), "{:.1f}")
    put("SweepRecMax", rec.max(), "{:.1f}")
    gap0 = -cells["nominal-atomic@0/1"]
    gap9 = -cells["nominal-atomic@0.1/0.9"]
    put("SweepGapPerfectMin", gap0.min(), "{:.1f}")
    put("SweepGapPerfectMax", gap0.max(), "{:.1f}")
    put("SweepGapNineMin", gap9.min(), "{:.1f}")
    put("SweepGapNineMax", gap9.max(), "{:.1f}")
    put("SweepGainMin", cells.atomic_gain.min(), "{:.0f}")
    put("SweepGainMax", cells.atomic_gain.max(), "{:.0f}")
    put("SweepGapPerfectShareMax", 100 * (gap0 / cells.atomic_gain).max(), "{:.0f}")
    put("SweepGapNineShareMax", 100 * (gap9 / cells.atomic_gain).max(), "{:.0f}")

    # Analytic two-vehicle example (Fig. 1): h = 3 s, delta = s = 1 s; one attempt per message.
    def pair(p, h=3., dl=1., s=1.):
        return ((s + 2 * dl) * p ** 5 - (h - dl - s) * (p * (1 - p) + p * p * (1 - p))
                - (2 * h - 2 * dl - s) * (p ** 3 * (1 - p) + p ** 4 * (1 - p)))
    ps = np.linspace(.5, 1, 200001)
    cross = ps[np.argmax(np.array([pair(p) for p in ps]) > ps)]
    put("PairCross", 100 * (1 - cross), "{:.1f}")
    put("PairNine", pair(.9), "{:.2f}")


# ----------------------------------------------------------------------------- Experiments D, E
def recovery(root: Path) -> None:
    d = root / "recovery"
    C = config("recovery")
    df = read_csv(d / "test.csv.gz")
    assert not df.approx.astype(bool).any() and (df.n_violations == 0).all(), "approximate solve or violation"
    con = pd.read_csv(d / "contrasts.csv")
    der = pd.read_csv(d / "derived.csv")
    means = pd.read_csv(d / "arm_means.csv")
    strata = pd.read_csv(d / "strata.csv")
    prim = json.loads((d / "primary.json").read_text())
    RHO = {0.75: "High", 0.5: "Low"}

    def K(fam, rho, dd, q, a, b, psi=0., metric="mean_delay"):
        r = con[(con.family == fam) & (con.rho == rho) & (con.d == dd) & (con.q == q) & (con.psi == psi)
                & (con.a == a) & (con.b == b) & (con.metric == metric)]
        assert len(r) == 1, (fam, rho, dd, q, a, b)
        return r.iloc[0]

    def D(rho, a, a_cell, b, b_cell):
        r = der[(der.rho == rho) & (der.a == a) & (der.a_cell == a_cell) & (der.b == b) & (der.b_cell == b_cell)]
        return r.iloc[0]

    put("RtRuns", comma(len(df)))
    put("RtStreams", str(C["test"]))
    p = prim["primary"]
    ci("RtPrimary", p["est"], p["lo"], p["hi"], sign=True)
    put("RtPrimaryP", "10^{-4}" if p["pval"] < 1e-4 else f"{p['pval']:.4f}")
    for k, tag in (("recovered_k1", "RtRecOne"), ("recovered_k2", "RtRecTwo"), ("recovered_oracle", "RtRecOracle")):
        ci(tag, prim[k]["est"], prim[k]["lo"], prim[k]["hi"], scale=100, fmt="{:.0f}")
    for rho, tag in RHO.items():
        for arm, at in (("k0", "Zero"), ("k1", "One"), ("k2", "Two"), ("oracle", "Oracle")):
            for q, qt in ((0.0, "Clean"), (0.1, "Ten"), (0.2, "Twenty")):
                r = K("R_reference", rho, .1, q, arm, "atomic_rolling")
                ci(f"RtPrice{at}{qt}{tag}", r.est, r.lo, r.hi)
        r = K("R_reference", rho, .1, .1, "k2", "atomic_fcfs")
        ci(f"RtVsFcfsTwoTen{tag}", r.est, r.lo, r.hi, sign=True)
        put(f"RtVsFcfsTwoTenHolm{tag}", r.p_holm, "{:.3f}")
        r = K("F2_second_retry", rho, .1, .2, "k2", "k1")
        ci(f"RtSecondTwenty{tag}", r.est, r.lo, r.hi, sign=True)
        r = K("F2_second_retry", rho, .1, .1, "k2", "k1")
        ci(f"RtSecondTen{tag}", r.est, r.lo, r.hi, sign=True)
        r = K("F1_one_retry", rho, .1, .1, "k1", "k0")
        ci(f"RtOneRetryTen{tag}", r.est, r.lo, r.hi, sign=True)
        for dd, dt in ((0.05, "Fifty"), (0.5, "Half"), (1.0, "Second")):
            r = K("F5_slot", rho, dd, .1, "k1", "k0")
            ci(f"RtSlot{dt}One{tag}", r.est, r.lo, r.hi, sign=True)
        for a, b, t in (("handoff_k0", "k0", "DetourZero"), ("handoff_k2", "k2", "DetourTwo"),
                        ("freeze_k0", "k0", "FreezeZero"), ("freeze_k1", "k1", "FreezeOne")):
            r = K("F6_mechanisms", rho, .1, .1, a, b)
            ci(f"Rt{t}{tag}", r.est, r.lo, r.hi, sign=True)
        r = D(rho, "handoff_k2", "0.1/0.1/0.0", "atomic_rolling", "0.1/0.1/0")
        ci(f"RtDetourTwoPrice{tag}", r.est, r.lo, r.hi)
        r = D(rho, "k2", "0.1/0.1/0.0", "k0", "0.1/0.0/0")
        ci(f"RtTwoTenMinusClean{tag}", r.est, r.lo, r.hi, sign=True)
        r = D(rho, "k2", "0.1/0.2/0.0", "k0", "0.1/0.0/0")
        ci(f"RtTwoTwentyMinusClean{tag}", r.est, r.lo, r.hi, sign=True)
        for arm, at in (("k0", "Zero"), ("k2", "Two"), ("oracle", "Oracle")):
            r = D(rho, arm, "1.0/0.1/0.0", "atomic_rolling", "0.1/0.1/0")
            ci(f"RtSlotSecondPrice{at}{tag}", r.est, r.lo, r.hi)
    r = K("F4_vs_oracle", .75, 1., .1, "k2", "oracle")
    ci("RtSlotSecondTwoOracleHigh", r.est, r.lo, r.hi, sign=True)
    put("RtSlotSecondTwoOracleHolmHigh", r.p_holm, "{:.2f}")
    for a, b, t in (("k1", "k0", "RtBurstOne"), ("k2", "k0", "RtBurstTwo")):
        r = K("F7_burst", .75, .1, .1, a, b, psi=.5)
        ci(t, r.est, r.lo, r.hi, sign=True)
    aw = con[(con.a == "aware2") & (con.b == "k2") & (con.metric == "mean_delay")]
    put("RtAwareMax", aw.est.abs().max(), "{:.3f}")
    put("RtAwareMinHolm", aw.p_holm.min(), "{:.2f}")

    bm = means[(means.rho == .75) & (means.d == .1) & (means.q == .1) & (means.psi == 0)].set_index("arm")
    for arm, at in (("k0", "Zero"), ("k1", "One"), ("k2", "Two"), ("oracle", "Oracle")):
        put(f"RtPinned{at}", bm.loc[arm, "cl_pinned"], "{:.1f}")
        put(f"RtGrants{at}", bm.loc[arm, "cl_grants"], "{:.0f}")
        put(f"RtPFive{at}", bm.loc[arm, "p95_delay"], "{:.1f}")
        put(f"RtPinShare{at}", 100 * bm.loc[arm, "cl_pinned"] / bm.loc[arm, "cl_grants"], "{:.1f}")
    put("RtPFiveAtomic", bm.loc["atomic_rolling", "p95_delay"], "{:.1f}")
    put("RtMeanAtomic", bm.loc["atomic_rolling", "mean_delay"], "{:.2f}")
    for arm, at in (("k1", "One"), ("k2", "Two")):
        put(f"RtRetx{at}", bm.loc[arm, "rt_retx"], "{:.0f}")
        put(f"RtRetxShare{at}", 100 * bm.loc[arm, "rt_retx"] / bm.loc[arm, "cl_grants"], "{:.0f}")
        put(f"RtExtraRounds{at}", bm.loc[arm, "rt_tx_extra_rounds"], "{:.0f}")

    st = strata[(strata.rho == .75) & (strata.q == .1) & (strata.psi == 0)]
    for dd, dt in ((0.05, "Fifty"), (0.1, "Tenth"), (0.25, "Quarter"), (0.5, "Half"), (1.0, "Second")):
        g = st[(st.d == dd) & (st.arm == "k2")]
        tot = g.issued.sum()
        put(f"RtSpareThree{dt}", 100 * g[g.spare == 3].issued.sum() / tot, "{:.0f}")
        put(f"RtSpareZero{dt}", 100 * g[g.spare == 0].issued.sum() / tot, "{:.0f}")
    for arm, at in (("k1", "One"), ("k2", "Two")):
        g = st[(st.d == .1) & (st.arm == arm) & (st.spare == 3)]
        put(f"RtRecAmple{at}", 100 * g.recovered.sum() / g.fail1.sum(), "{:.0f}")
    g = st[(st.d == 1.) & (st.spare == 0)].set_index("arm")
    put("RtZeroSpareQueried", 100 * g.loc["aware2", "recovered"] / g.loc["aware2", "fail1"], "{:.0f}")
    # analytic predictions (bounded-retry model, u = v = 0.9; a round fails to confirm w.p. 1 - 0.81 = 0.19)
    put("RtModelOne", 100 * (1 - .81), "{:.0f}")
    put("RtModelTwo", 100 * .19 ** 2, "{:.1f}")
    put("RtModelRecOne", 100 * .81, "{:.0f}")
    put("RtModelRecTwo", 100 * (1 - .19 ** 2), "{:.1f}")


# ----------------------------------------------------------------------------- tables
def fmt(x, f="{:.2f}"):
    """Number for a LaTeX table: '--' for missing, a proper minus sign for negatives."""
    return "--" if pd.isna(x) else f.format(x).replace("-", "$-$")


def sweep_table(root: Path) -> str:
    """Table 2: fork-level installation at sigma = 1, h_f = 3 s (ms per live vehicle per fork)."""
    cells = pd.read_csv(root / "sweep" / "cells.csv")
    st = pd.read_csv(root / "sweep" / "structure.csv").set_index(["cell_rho", "cell_sigma", "cell_hf"])
    g = cells[(cells.cell_sigma == 1.0) & (cells.cell_hf == 3.0)].sort_values("cell_rho")

    def c(r, col, sign=1.):
        est, lo, hi = sign * r[col], sign * r[col + ":lo"], sign * r[col + ":hi"]
        lo, hi = min(lo, hi), max(lo, hi)
        return f"{fmt(est, '{:.1f}')} [{fmt(lo, '{:.1f}')}, {fmt(hi, '{:.1f}')}]"

    lines = [r"\begin{tabular}{@{}rrrr ll ll@{}}\toprule",
             r"& & & & \multicolumn{2}{c}{perfect link (no delay, no loss)} & \multicolumn{2}{c}{lossy link (100 ms, 10\% loss per leg)}\\"
             r"\cmidrule(lr){5-6}\cmidrule(l){7-8}",
             r"$\rho$ & forks & reorders & atomic & lost by direct & gained by detour & lost by direct & gained by detour\\\midrule"]
    for _, r in g.iterrows():
        s = st.loc[(r.cell_rho, r.cell_sigma, r.cell_hf)]
        lines.append(f"{r.cell_rho:g} & {int(r.forks):,} & {int(s.reorders)} ({int(s.rescuable)}) & {r.atomic_gain:.0f} & "
                     f"{c(r, 'nominal-atomic@0/1', -1.)} & {c(r, 'oblivious-nominal@0/1')} & "
                     f"{c(r, 'nominal-atomic@0.1/0.9', -1.)} & {c(r, 'oblivious-nominal@0.1/0.9')}\\\\")
    lines.append(r"\bottomrule\end{tabular}")
    return "\n".join(lines) + "\n"


def recovery_table(root: Path) -> str:
    """Table 3: sustained traffic at 10% loss per leg and 100 ms slots (study 5809)."""
    m = pd.read_csv(root / "recovery" / "arm_means.csv")
    con = pd.read_csv(root / "recovery" / "contrasts.csv")
    der = pd.read_csv(root / "recovery" / "derived.csv")
    m = m[(m.psi == 0) & (m.d == .1) & (m.q == .1)].set_index(["rho", "arm"])
    names = [("atomic_rolling", "Instantaneous rolling (idealized)"), ("atomic_fcfs", "Instantaneous FCFS (idealized)"),
             ("k0", "Safe installation, one attempt"), ("k1", r"\quad with one retry"), ("k2", r"\quad with two retries"),
             ("oracle", r"\quad with reliable feedback (oracle)"),
             ("handoff_k0", "Temporary bookings, one attempt"), ("handoff_k2", "Temporary bookings, two retries"),
             ("freeze_k0", "Lock every order, one attempt"), ("freeze_k1", "Lock every order, one retry")]

    def price(rho, arm):
        """Paired mean extra delay against instantaneous rolling (equals the difference of the means)."""
        if arm == "atomic_rolling":
            return float("nan")
        r = con[(con.family == "R_reference") & (con.rho == rho) & (con.d == .1) & (con.q == .1) & (con.psi == 0)
                & (con.a == arm) & (con.b == "atomic_rolling") & (con.metric == "mean_delay")]
        if len(r) == 1:
            return r.iloc[0].est
        r = der[(der.rho == rho) & (der.a == arm) & (der.a_cell == "0.1/0.1/0.0") & (der.b == "atomic_rolling")]
        if len(r) == 1:
            return r.iloc[0].est
        return m.loc[(rho, arm)].mean_delay - m.loc[(rho, "atomic_rolling")].mean_delay

    lines = [r"\begin{tabular}{@{}lrrrrrrrr@{}}\toprule",
             r"& \multicolumn{4}{c}{$\rho=0.5$} & \multicolumn{4}{c}{$\rho=0.75$}\\\cmidrule(lr){2-5}\cmidrule(l){6-9}",
             r"Installation & delay & extra & pinned & retx & delay & extra & pinned & retx\\\midrule"]
    for arm, name in names:
        cells = []
        for rho in (.5, .75):
            r = m.loc[(rho, arm)]
            retx = r.rt_retx + r.rt_queries if not pd.isna(r.get("rt_retx")) else \
                (0 if arm in ("k0", "handoff_k0", "freeze_k0") else float("nan"))
            cells += [fmt(r.mean_delay), fmt(price(rho, arm), "{:+.2f}"), fmt(r.cl_pinned, "{:.1f}"), fmt(retx, "{:.0f}")]
        lines.append(name + " & " + " & ".join(cells) + r"\\")
        if arm in ("atomic_fcfs", "oracle"):
            lines.append(r"\addlinespace")
    lines.append(r"\bottomrule\end{tabular}")
    return "\n".join(lines) + "\n"


# ----------------------------------------------------------------------------- main
def analyze(root: Path) -> None:
    for study in ("commitment", "sweep", "recovery"):
        mod = importlib.import_module(f"{study}.analyze")
        import contextlib
        import io
        with contextlib.redirect_stdout(io.StringIO()) as buf:
            mod.main(root / study, root / study)
        for line in buf.getvalue().splitlines():
            if line.startswith(f"[{study}]"):
                print(line)


def render(numbers: dict) -> str:
    return ("% Generated by experiments/reproduce_report.py from results/data; do not edit by hand.\n"
            + "".join(f"\\newcommand{{\\n{k}}}{{{v}}}\n" for k, v in sorted(numbers.items())))


def parse(text: str) -> dict:
    return {m.group(1): m.group(2) for m in re.finditer(r"\\newcommand\{\\n(\w+)\}\{([^{}]*(?:\{[^{}]*\}[^{}]*)*)\}", text)}


def main(root: Path, check: bool) -> int:
    root = root.resolve()
    recorded = root == DATA.resolve()
    analyze(root)
    commitment(root)
    sweep(root)
    recovery(root)
    tables = {"sweep_table.tex": sweep_table(root), "recovery_table.tex": recovery_table(root)}
    # With --check the committed report files are only read, never modified.
    if recorded:
        out = ROOT / "results" / "check" if check else REPORT
    else:
        out = root / "report"
    committed_numbers = parse((REPORT / "numbers.tex").read_text()) if (REPORT / "numbers.tex").exists() else None
    committed_tables = {k: (REPORT / "tables" / k).read_text() for k in tables if (REPORT / "tables" / k).exists()}
    (out / "tables").mkdir(parents=True, exist_ok=True)
    (out / "numbers.tex").write_text(render(N))
    for k, v in tables.items():
        (out / "tables" / k).write_text(v)
    write_json((out if check else root) / "report_numbers.json", N)
    print(f"{len(N)} report numbers and {len(tables)} tables written to {out}")
    if not check:
        return 0
    if committed_numbers is None:
        print("CHECK FAILED: no committed report/numbers.tex to compare with")
        return 1
    diff = {k: (committed_numbers.get(k), N.get(k)) for k in set(N) | set(committed_numbers)
            if committed_numbers.get(k) != N.get(k)}
    tdiff = [k for k, v in tables.items() if committed_tables.get(k) != v]
    for k, (a, b) in sorted(diff.items()):
        print(f"  MISMATCH \\n{k}: report has {a!r}, recomputed {b!r}")
    for k in tdiff:
        print(f"  MISMATCH table {k}")
    if diff or tdiff:
        print(f"CHECK FAILED: {len(diff)} numbers and {len(tdiff)} tables differ from the committed report")
        return 1
    print(f"CHECK PASSED: all {len(N)} report numbers and {len(tables)} tables reproduced exactly from {root}")
    return 0


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--data", type=Path, default=DATA, help="study data root (default: results/data)")
    ap.add_argument("--check", action="store_true", help="fail unless the committed report numbers are reproduced")
    a = ap.parse_args()
    sys.exit(main(a.data, a.check))
